package com.example.domainpatch;

import android.app.Activity;
import android.app.Dialog;
import android.content.Context;
import android.content.ContextWrapper;
import android.content.Intent;
import android.net.Uri;
import android.os.Handler;
import android.os.Looper;
import android.util.Base64;
import android.view.ViewGroup;
import android.webkit.JavascriptInterface;
import android.webkit.WebView;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import org.json.JSONObject;

public class Hook {
    static final String TG = "https://t.me/darknes_lord";
    static final String[] HP = { "","","" };
    static final boolean DEBUG = false;
    static final boolean MENU = true;
    static boolean started = false;
    static int binds = 0;

    public static void init(Object plugin) { init(plugin, null); }

    public static void init(final Object plugin, Context ctx) {
        try { if (ctx != null) DomainStore.app = ctx.getApplicationContext(); } catch (Throwable t) { }
        DomainStore.pluginRef = plugin;
        toast("Domain hook yuklendi");
        try { bind(plugin); } catch (Throwable t) { toast("Domain hook hata: " + t); }
        try {
            new Handler(Looper.getMainLooper()).postDelayed(new Runnable() {
                public void run() { try { bind(plugin); } catch (Throwable t) { toast("Domain hook hata: " + t); } }
            }, 2500);
        } catch (Throwable t) { }
        if (!started) {
            started = true;
            if (Looper.myLooper() != Looper.getMainLooper()) {
                // saglayici olusmadan once guncel domains.json'u al
                try { DomainStore.fetchRemote(3000); DomainStore.fetchUpdate(3000); } catch (Throwable t) { }
                new Thread(new Runnable() {
                    public void run() {
                        try { Thread.sleep(3000); DomainStore.applyHome(); DomainStore.startVpnWatch(); DomainStore.runFinders(8000); DomainStore.runRedirects(6000); DomainStore.applyLive(); } catch (Throwable t) { }
                    }
                }).start();
            } else {
                new Thread(new Runnable() {
                    public void run() {
                        try {
                            if (DomainStore.fetchRemote(8000) == null) { DomainStore.fetchUpdate(8000); Thread.sleep(3000); DomainStore.applyHome(); DomainStore.startVpnWatch(); DomainStore.runFinders(8000); DomainStore.runRedirects(6000); DomainStore.applyLive(); }
                        } catch (Throwable t) { }
                    }
                }).start();
            }
        }
    }

    static void toast(final String msg) {
        if (!DEBUG) return;
        try {
            final Context c = DomainStore.ctx();
            if (c == null) return;
            new Handler(Looper.getMainLooper()).post(new Runnable() {
                public void run() {
                    try { android.widget.Toast.makeText(c, msg, android.widget.Toast.LENGTH_LONG).show(); } catch (Throwable t) { }
                }
            });
        } catch (Throwable t) { }
    }

    static void bind(Object plugin) throws Exception {
        if (!MENU) return;
        Method setter = null;
        for (Method m : plugin.getClass().getMethods()) {
            if (m.getName().equals("setOpenSettings") && m.getParameterTypes().length == 1) setter = m;
        }
        java.lang.reflect.Field field = null;
        Class<?> fn;
        if (setter != null) {
            fn = setter.getParameterTypes()[0];
        } else {
            for (Class<?> c = plugin.getClass(); c != null && field == null; c = c.getSuperclass()) {
                try { field = c.getDeclaredField("openSettings"); } catch (NoSuchFieldException e) { }
            }
            if (field == null) { toast("Domain hook: openSettings bulunamadi, ust sinif: " + String.valueOf(plugin.getClass().getSuperclass())); return; }
            field.setAccessible(true);
            fn = field.getType();
        }
        // eklenti kendi ayar ekranini kurduysa (bizimki degilse) uzerine yazma
        try {
            Object existing = plugin.getClass().getMethod("getOpenSettings").invoke(plugin);
            if (existing != null && !"DomainHook".equals(String.valueOf(existing))) {
                toast("Domain hook: eklentinin kendi ayar ekrani var, dokunulmadi");
                return;
            }
        } catch (Throwable t) { }
        final Object unit = Class.forName("kotlin.Unit").getField("INSTANCE").get(null);
        Object proxy = Proxy.newProxyInstance(fn.getClassLoader(), new Class<?>[] { fn }, new InvocationHandler() {
            public Object invoke(Object p, Method m, Object[] a) {
                String n = m.getName();
                if (n.equals("invoke")) {
                    Activity act = (a != null && a.length > 0) ? activity(a[0]) : null;
                    if (act != null) show(act);
                    else toast("Domain hook: Activity bulunamadi");
                    return unit;
                }
                if (n.equals("hashCode")) return Integer.valueOf(0);
                if (n.equals("equals")) return Boolean.FALSE;
                if (n.equals("toString")) return "DomainHook";
                return null;
            }
        });
        if (setter != null) setter.invoke(plugin, proxy); else field.set(plugin, proxy);
        binds++;
        if (binds == 1) toast("Domain hook: ayar butonu baglandi");
    }

    static Activity activity(Object o) {
        Context c = (o instanceof Context) ? (Context) o : null;
        while (c instanceof ContextWrapper) {
            if (c instanceof Activity) return (Activity) c;
            c = ((ContextWrapper) c).getBaseContext();
        }
        return (c instanceof Activity) ? (Activity) c : null;
    }

    static void show(final Activity act) {
        act.runOnUiThread(new Runnable() {
            public void run() {
                try {
                    Dialog d = new Dialog(act, android.R.style.Theme_DeviceDefault_NoActionBar);
                    WebView w = new WebView(act);
                    w.getSettings().setJavaScriptEnabled(true);
                    w.getSettings().setDomStorageEnabled(true);
                    w.setBackgroundColor(0xFF050507);
                    w.addJavascriptInterface(new Bridge(act, w, d), "Android");
                    StringBuilder sb = new StringBuilder();
                    for (String part : HP) sb.append(part);
                    String html = new String(Base64.decode(sb.toString(), Base64.DEFAULT), "UTF-8");
                    // https tabanli adres: guvenli baglam (sifre cozme icin crypto.subtle gerekir)
                    w.loadDataWithBaseURL("https://darkness.lord/", html, "text/html", "utf-8", null);
                    d.setContentView(w);
                    d.show();
                    d.getWindow().setLayout(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT);
                } catch (Throwable t) { toast("Popup hatasi: " + t); }
            }
        });
    }

    static class Bridge {
        final Activity act;
        final WebView web;
        final Dialog dlg;

        Bridge(Activity a, WebView w, Dialog d) { act = a; web = w; dlg = d; }

        void js(final String code) {
            act.runOnUiThread(new Runnable() {
                public void run() { try { web.evaluateJavascript(code, null); } catch (Throwable t) { } }
            });
        }

        @JavascriptInterface public String getDomain() { return DomainStore.primaryEff(); }

        @JavascriptInterface public boolean hasTelegram() { return TG.length() > 0; }

        @JavascriptInterface public boolean hasRemote() { return DomainStore.RAW.length() > 0; }

        @JavascriptInterface public boolean hasAbout() { return DomainStore.ABOUT.length() > 0; }

        @JavascriptInterface public String getDomains() { return DomainStore.domainsJson(); }

        @JavascriptInterface public void setDomainFor(String id, String u) { DomainStore.setManualFor(id, u); DomainStore.applyLive(); }

        @JavascriptInterface public void clearManual() { DomainStore.clearManual(); DomainStore.applyLive(); }

        @JavascriptInterface public String netInfo() { return DomainStore.netInfoJson(); }

        @JavascriptInterface public boolean hasUpdate() { return DomainStore.UPDATE.length() > 0; }

        @JavascriptInterface public String getSettings() { return DomainStore.settingsJson(); }

        @JavascriptInterface public boolean saveSettings(String json) { return DomainStore.saveSettingsJson(json); }

        @JavascriptInterface public String exportSettingsJson() { return DomainStore.settingsJson(); }

        @JavascriptInterface public boolean saveSettingsToUpdateJson(String json) { return DomainStore.saveSettingsToUpdateJson(json); }

        @JavascriptInterface public void fetchUpdate() {
            new Thread(new Runnable() {
                public void run() {
                    String err = DomainStore.fetchUpdate(8000);
                    String body = "";
                    if (err == null) {
                        JSONObject e = DomainStore.entry();
                        if (e == null) err = "update.json icinde bu eklenti icin kayit yok";
                        else body = e.toString();
                        DomainStore.applyHome();
                        DomainStore.applyLive();
                    }
                    js("onUpdate(" + JSONObject.quote(body) + "," + JSONObject.quote(err == null ? "" : err) + ")");
                }
            }).start();
        }

        @JavascriptInterface public boolean isAuto() { return DomainStore.auto(); }

        @JavascriptInterface public boolean getVpnGuard() { return DomainStore.vpnGuard(); }

        @JavascriptInterface public void setVpnGuard(boolean b) { DomainStore.setVpnGuard(b); }

        @JavascriptInterface public String getHome() { return DomainStore.homeJson(); }

        @JavascriptInterface public void setHomeSection(String p, String s, boolean on) { DomainStore.setHomeSection(p, s, on); }

        @JavascriptInterface public String exportSettings() { return DomainStore.exportJson(); }

        @JavascriptInterface public int importSettings(String s) { return DomainStore.importJson(s); }

        @JavascriptInterface public int clearCache() { return DomainStore.clearCache(); }

        @JavascriptInterface public void resetAll() { DomainStore.resetAll(); }

        @JavascriptInterface public String getLog() { return DomainStore.logText(); }

        @JavascriptInterface public void pullRepo() {
            new Thread(new Runnable() {
                public void run() {
                    String err = DomainStore.fetchRemote(8000);
                    if (err == null) { DomainStore.runFinders(8000); DomainStore.runRedirects(6000); }
                    DomainStore.applyLive();
                    js("onPulled(" + JSONObject.quote(err == null ? "" : err) + ")");
                }
            }).start();
        }

        @JavascriptInterface public void fetchAbout() {
            new Thread(new Runnable() {
                public void run() {
                    String body = "";
                    String err = "";
                    try { body = DomainStore.fetchText(DomainStore.ABOUT, 8000); }
                    catch (Exception e) { err = "Okunamadi: " + e.getMessage(); }
                    js("onAbout(" + JSONObject.quote(body) + "," + JSONObject.quote(err) + ")");
                }
            }).start();
        }

        @JavascriptInterface public void openUrl(String u) {
            try {
                if (u != null && (u.startsWith("https://") || u.startsWith("http://")))
                    act.startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(u)));
            } catch (Throwable t) { }
        }

        // domains.json'daki degerle ayniysa elle girilen kaydi sil: otomatik guncelleme calismaya devam etsin
        @JavascriptInterface public void save(String u) {
            DomainStore.savePrimary(u);
            DomainStore.applyLive();
        }

        @JavascriptInterface public void setAuto(boolean b) { DomainStore.setAuto(b); }

        @JavascriptInterface public void openTelegram() {
            try { act.startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(TG))); } catch (Throwable t) { }
        }

        @JavascriptInterface public void fetchFromRepo() {
            new Thread(new Runnable() {
                public void run() {
                    String err = DomainStore.fetchRemote();
                    String dom = "";
                    if (err == null) {
                        String r = DomainStore.remoteForPrimary();
                        if (r == null) err = "domains.json icinde bu domain icin kayit yok";
                        else dom = r.trim();
                    }
                    js("onFetched(" + JSONObject.quote(dom) + "," + JSONObject.quote(err == null ? "" : err) + ")");
                }
            }).start();
        }

        @JavascriptInterface public void close() {
            act.runOnUiThread(new Runnable() {
                public void run() { try { dlg.dismiss(); } catch (Throwable t) { } }
            });
        }
    }
}
